    o+='<text x="'+(W-20)+'" y="'+(H-14)+'" text-anchor="end" class="tc">ОРИЕНТИРОВЪЧНА СХЕМА · РАЗМЕРИ В CM</text>'+wmLogo(W,H,.5,.05)+'</svg>';return o;
