    store('pdShopFav',favs);
    $$('[data-fav="'+id+'"]').forEach(function(x){x.setAttribute('aria-pressed',i<0);x.classList.remove('pop');void x.offsetWidth;x.classList.add('pop')});
    counts('fav');
