      var F=FIN[fin];obj.style.setProperty('--c-front',F.front);obj.style.setProperty('--c-edge',F.edge);obj.style.setProperty('--c-top',F.top);obj.style.setProperty('--c-side',F.side);obj.style.setProperty('--grain',F.grain);
