    var cb=$('#s-cart-btn'),fb=$('#s-fav-btn'),x=$('#s-x'),sc=$('#s-scrim');
    if(cb)cb.onclick=function(){openDrawer('cart')};
    if(fb)fb.onclick=function(){openDrawer('fav')};
